const video=$('camera-video');
const camera=new CameraController({video,onEnded:()=>{stopCamera();$('status').textContent='Camera disconnected. Reconnect it and choose Use camera to try again.';}});
const hasSource=()=>cameraMode?live:!!photo;
const sourceSize=()=>live?{width:video.videoWidth,height:video.videoHeight}:{width:photo?.width||0,height:photo?.height||0};
function draw(check=true){if(!hasSource())return;const source=live?video:photo;const size=sourceSize();if(!size.width||!size.height)return;ctx.fillStyle='#fff';ctx.fillRect(0,0,630,810);const w=size.width*base*scale,h=size.height*base*scale;x=Math.min(Math.max(x,(630-w)/2),(w-630)/2);y=Math.min(Math.max(y,(810-h)/2),(h-810)/2);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(source,(630-w)/2+x,(810-h)/2+y,w,h);if(check)scheduleChecks();}
