function syncSourceUI(){const available=hasSource();$('empty').hidden=available;$('crop').hidden=!available;$('zoom').disabled=!available;$('reset').disabled=!available;$('download').disabled=!photo||cameraMode;$('camera-settings').hidden=!cameraMode;$('camera-actions').hidden=!cameraMode;$('camera-live').hidden=!live;$('take-photo').disabled=!live;$('camera-select').disabled=!live;$('refresh-cameras').disabled=!live;$('cameramode').classList.toggle('active',cameraMode);$('cameramode').setAttribute('aria-pressed',String(cameraMode));$('uploadmode').classList.toggle('active',!cameraMode);$('uploadmode').setAttribute('aria-pressed',String(!cameraMode));document.querySelector('.editor').classList.toggle('camera-active',cameraMode);if(cameraMode)$('download').textContent='Take a photo to download';}
function clearLiveLoop(){cancelAnimationFrame(previewFrame);clearInterval(liveTimer);previewFrame=liveTimer=null;}
function stopCamera(restore=true){cameraEpoch++;clearLiveLoop();camera.stop();live=false;cameraMode=false;revision++;clearTimeout(checkTimer);checkTimer=null;if(restore&&priorCrop){({base,scale,x,y}=priorCrop);$('zoom').value=scale;}priorCrop=null;syncSourceUI();if(photo)draw();else{$('checksummary').classList.remove('busy');$('checksummary').textContent='Upload a photo or start your camera to run automatic checks.';$('checkresults').replaceChildren();$('retrychecks').hidden=true;}$('camera-status').textContent='Camera is off.';}
async function refreshCameras(selected){const devices=await camera.devices();const select=$('camera-select'),previous=select.value,keep=selected||previous;select.replaceChildren();for(const [i,device] of devices.entries()){const option=document.createElement('option');option.value=device.deviceId;option.textContent=device.label||`Camera ${i+1}`;select.append(option);}if(devices.some(d=>d.deviceId===keep))select.value=keep;else if(devices.some(d=>d.deviceId===previous))select.value=previous;else if(!devices.length){const option=document.createElement('option');option.textContent='No cameras available';option.value='';select.append(option);}return devices;}
async function startCamera(deviceId){if(!cameraMode)priorCrop={base,scale,x,y};cameraMode=true;live=false;clearLiveLoop();const epoch=++cameraEpoch;revision++;clearTimeout(checkTimer);checkTimer=null;analysisPaused=false;syncSourceUI();$('camera-status').textContent='Starting camera… Allow camera access if your browser asks. Microphone access is not requested.';$('checksummary').textContent='Waiting for the camera…';$('checksummary').classList.remove('busy');$('checkresults').replaceChildren();
  try{const info=await camera.open(deviceId);if(!info||epoch!==cameraEpoch)return;live=true;base=Math.max(630/info.width,810/info.height);scale=1;x=y=0;$('zoom').value=1;syncSourceUI();$('camera-status').textContent=`Live · ${info.width} × ${info.height}. Checks sample about once a second; first use may take longer.`;$('status').textContent='Live view is not mirrored. Drag or zoom to frame your head, then take a photo.';try{await refreshCameras(info.deviceId);}catch{$('camera-status').textContent='Live camera is ready. Camera list could not refresh.';}if(epoch!==cameraEpoch)return;draw();function preview(time){if(!live||epoch!==cameraEpoch)return;if(time-lastDraw>=33){draw(false);lastDraw=time;}previewFrame=requestAnimationFrame(preview);}previewFrame=requestAnimationFrame(preview);liveTimer=setInterval(()=>{if(live&&!inFlight&&!checkTimer&&!analysisPaused&&!document.hidden)runChecks();},1000);
  }catch(error){if(epoch!==cameraEpoch)return;live=false;syncSourceUI();$('camera-status').textContent=cameraError(error);$('checksummary').textContent='Camera is not running. Retry Use camera, choose another camera, or upload a photo.';$('status').textContent='Camera did not start. Your existing photo is preserved.';try{await refreshCameras();$('camera-select').disabled=false;$('refresh-cameras').disabled=false;}catch{/* The main error already gives a retry path. */}}
}
async function takePhoto(){if(!live)return;const epoch=cameraEpoch,frame=document.createElement('canvas');frame.width=video.videoWidth;frame.height=video.videoHeight;frame.getContext('2d').drawImage(video,0,0);$('take-photo').disabled=true;$('camera-status').textContent='Capturing photo…';let next;
  try{const blob=await new Promise(resolve=>frame.toBlob(resolve,'image/png'));if(!blob)throw new Error('Capture failed');next=URL.createObjectURL(blob);const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=next;});if(epoch!==cameraEpoch){URL.revokeObjectURL(next);return;}stopCamera(false);if(url)URL.revokeObjectURL(url);url=next;photo=img;base=Math.max(630/img.width,810/img.height);analysisPaused=false;syncSourceUI();draw();$('status').textContent='Photo captured. Camera is off. Review the still-photo checks, adjust the crop, and download.';
  }catch{if(next)URL.revokeObjectURL(next);if(epoch!==cameraEpoch)return;$('take-photo').disabled=false;$('camera-status').textContent='Could not capture this frame. Please try again.';}}
async function load(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){$('status').textContent='Please choose a JPG, PNG, or WebP image.';return;}if(file.size>40*1024*1024){$('status').textContent='Please choose a photo smaller than 40 MB.';return;}let next;
  try{next=URL.createObjectURL(file);const img=new Image();await new Promise((ok,fail)=>{img.onload=ok;img.onerror=fail;img.src=next;});stopCamera(false);if(url)URL.revokeObjectURL(url);url=next;photo=img;base=Math.max(630/img.width,810/img.height);analysisPaused=false;syncSourceUI();reset();$('status').textContent=img.width<630||img.height<810?'This image is smaller than the output. A higher-resolution original will give better detail.':'Drag to position your head, then use zoom to match the guides.';}catch{if(next)URL.revokeObjectURL(next);$('status').textContent='This photo could not be opened. Please try another image.';}}
$('cameramode').onclick=()=>startCamera($('camera-select').value||undefined);
$('uploadmode').onclick=()=>{if(cameraMode)stopCamera();};
$('camera-select').onchange=()=>startCamera($('camera-select').value);
$('refresh-cameras').onclick=()=>refreshCameras().catch(()=>{$('camera-status').textContent='Could not refresh cameras. Try reopening camera mode.';});
$('take-photo').onclick=takePhoto;$('stop-camera').onclick=()=>{stopCamera();$('status').textContent='Camera stopped. Upload a photo or reopen the camera.';};
navigator.mediaDevices?.addEventListener?.('devicechange',()=>{if(cameraMode)refreshCameras().catch(()=>{});});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&cameraMode){stopCamera();$('status').textContent='Camera stopped because this tab was hidden. Choose Use camera to resume.';}});
window.addEventListener('pagehide',()=>{camera.stop();clearLiveLoop();});
$('upload').onclick=$('replace').onclick=()=>$('file').click();$('file').onchange=e=>{load(e.target.files[0]);e.target.value='';};$('zoom').oninput=e=>{scale=+e.target.value;draw();};$('reset').onclick=reset;$('showguides').onchange=e=>$('guides').hidden=!e.target.checked;
$('crop').onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,ox:x,oy:y};$('crop').setPointerCapture(e.pointerId);};$('crop').onpointermove=e=>{if(!drag)return;const ratio=630/canvas.getBoundingClientRect().width;x=drag.ox+(e.clientX-drag.x)*ratio;y=drag.oy+(e.clientY-drag.y)*ratio;draw();};$('crop').onpointerup=$('crop').onpointercancel=()=>drag=null;
for(const event of ['dragenter','dragover'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.add('dragging');});$('drop').ondragleave=()=>$('drop').classList.remove('dragging');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('dragging');load(e.dataTransfer.files[0]);};
$('download').onclick=()=>{if(!photo||cameraMode)return;draw(false);const type=$('format').value;canvas.toBlob(blob=>{if(!blob){$('status').textContent='Export failed. Please try again.';return;}const link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download='indian-passport-630x810.'+(type==='image/png'?'png':'jpg');link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('status').textContent=`Downloaded 630 × 810 px · ${Math.round(blob.size/1024)} KB. Review your photo before submitting.`;},type,.95);};
function markPending(message='Checking your latest crop…'){$('checksummary').textContent=message;$('checksummary').classList.add('busy');document.querySelectorAll('.checkrow').forEach(row=>row.classList.add('busy'));$('download').textContent=cameraMode?'Take a photo to download':'Download photo · checks pending ↓';}
function scheduleChecks(){revision++;clearTimeout(checkTimer);analysisPaused=false;markPending(worker?'Checking your latest crop…':'Preparing on-device checks… First use loads the photo models.');checkTimer=setTimeout(()=>{checkTimer=null;runChecks();},450);}
function analysisError(message){analysisPaused=true;$('checksummary').textContent=message;$('checksummary').classList.remove('busy');$('checkresults').replaceChildren();const row=document.createElement('p');row.className='checkplaceholder';row.textContent='Photo not verified. Automatic checks are unavailable; you can still capture or download a crop at 630 × 810 pixels.';$('checkresults').append(row);$('retrychecks').hidden=false;$('download').textContent=cameraMode?'Take a photo to download':'Download without verification ↓';}
function ensureWorker(){if(worker)return;const generation=++workerGeneration;worker=new Worker('./check-worker.js?v=2');worker.onmessage=({data})=>{if(generation!==workerGeneration)return;clearTimeout(checkTimeout);inFlight=false;if(data.id!==revision){runChecks();return;}if(data.error){worker.terminate();worker=null;analysisError(data.error);return;}renderChecks(data.rows);if(live)$('camera-status').textContent=`Live · Latest check ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}. Take a photo when ready.`;};worker.onerror=()=>{if(generation!==workerGeneration)return;clearTimeout(checkTimeout);inFlight=false;worker.terminate();worker=null;analysisError('Automatic checks could not start in this browser. Try again, or use a browser with WebAssembly support.');};}
