  const warnings=rows.filter(r=>r.status==='warn'),unknown=rows.filter(r=>r.status==='review'),passed=rows.filter(r=>r.status==='pass');
  $('checksummary').textContent=warnings.length?`${warnings.length} need attention · ${passed.length} look good${unknown.length?` · ${unknown.length} unverified`:''}`:unknown.length?`${unknown.length} unverified · ${passed.length} look good`:`All ${passed.length} checks look good. Results are estimates.`;
  const panel=$('checkresults'),expanded=new Map([...panel.querySelectorAll('details[data-check]')].map(el=>[el.dataset.check,el.open])),passesOpen=panel.querySelector('.passed-checks')?.open;panel.replaceChildren();
  function makeRow(result){const row=document.createElement('details');row.className='checkrow '+result.status;row.dataset.check=result.id;row.open=expanded.has(result.id)?expanded.get(result.id):result.status==='warn';const head=document.createElement('summary');head.className='checkrow-head';const title=document.createElement('span');title.className='checkrow-title';title.textContent=result.title;const badge=document.createElement('span');badge.className='checkbadge';badge.textContent={pass:'✓ Looks good',warn:'! Needs attention',review:'? Unverified'}[result.status];const detail=document.createElement('p');detail.textContent=result.detail;head.append(title,badge);row.append(head,detail);return row;}
